SELECT compound_structures.canonical_smiles, molecule_dictionary.chembl_id, activities.standard_type, activities.standard_relation, activities.standard_value, activities.standard_units FROM activities JOIN assays ON activities.assay_id = assays.assay_id JOIN molecule_dictionary ON activities.molregno = molecule_dictionary.molregno JOIN compound_structures ON molecule_dictionary.molregno = compound_structures.molregno WHERE assays.chembl_id = 'CHEMBL1613918' AND activities.standard_value IS NOT NULL AND activities.standard_relation = '=' ORDER BY compound_structures.canonical_smiles, molecule_dictionary.chembl_id, activities.standard_type, activities.standard_relation, activities.standard_value, activities.standard_units
